.rhythm{padding:14px 22px 18px;background:linear-gradient(180deg,#171e2e,#121826)}.rhythm-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.section-title{font-size:11px;font-weight:900;letter-spacing:.15em;color:#e8eaf5}.instruction{font-size:10px;color:#9da7bf}.instruction b{color:#e8eaf5}.lane-board{height:174px;position:relative;overflow:hidden;border-radius:13px;border:1px solid #ffffff13;background:#101624;display:grid;grid-template-columns:repeat(4,1fr);touch-action:none}.lane{position:relative;border-right:1px solid #ffffff12;background:linear-gradient(180deg,#ffffff03,#ffffff00)}.lane:nth-child(even){background:linear-gradient(180deg,#ffffff08,#ffffff00)}.lane:last-child{border:0}.lane.active{background:linear-gradient(180deg,#ffffff16,#ffffff02)}.lane .key{position:absolute;bottom:7px;left:50%;transform:translateX(-50%);z-index:3;width:34px;height:27px;border:1px solid #ffffff28;border-radius:8px;background:#232c3f;color:#b9c3d9;display:grid;place-items:center;font-size:11px;font-weight:900;box-shadow:0 3px 0 #090e18}.lane:nth-child(1){--color:#55dfcb}.lane:nth-child(2){--color:#9e86ff}.lane:nth-child(3){--color:#ffcb66}.lane:nth-child(4){--color:#ff758f}.lane .key:after{content:"";position:absolute;inset:0;border-radius:7px;background:var(--color);opacity:0;transition:.08s}.lane.active .key:after{opacity:.55}.hitline{position:absolute;left:0;right:0;bottom:39px;height:3px;background:linear-gradient(90deg,transparent,#ffffffbb 15%,#ffffffbb 85%,transparent);box-shadow:0 0 12px #fff8;z-index:2;pointer-events:none}.note{position:absolute;left:50%;width:40px;height:18px;transform:translate(-50%,-50%);border-radius:7px;background:var(--color);box-shadow:0 0 15px color-mix(in srgb,var(--color),transparent 25%),inset 0 2px #ffffff77;z-index:1}.note:after{content:"";position:absolute;inset:4px 8px;border-radius:9px;background:#ffffffa8}.note.hit{animation:pop .22s ease-out forwards}.@keyframes pop{to{opacity:0;transform:translate(-50%,-50%) scale(2)}}
.bottom{display:flex;align-items:center;justify-content:space-between;margin-top:12px;gap:12px}.stats{display:flex;gap:19px}.stat label{display:block;color:#929db6;font-size:9px;font-weight:800;letter-spacing:.12em}.stat strong{font-size:15px;display:block;margin-top:3px}.stat strong.combo{color:#ffd277}.meter{height:4px;width:110px;background:#30374a;border-radius:4px;margin-top:6px;overflow:hidden}.meter span{display:block;background:linear-gradient(90deg,#9e86ff,#6beac1);height:100%;width:0;transition:width .2s}.status{font-size:10px;color:#adb6ca;text-align:right;min-width:120px}.controls{height:52px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);background:#141b29;color:#909bb3;font-size:10px}.controls strong{color:#d9deef}.controlright{display:flex;gap:8px;align-items:center}.controlright button{border:1px solid #ffffff1a;background:#20283a;border-radius:8px;padding:7px 10px;font-size:10px;font-weight:800;cursor:pointer}.controlright button:hover{background:#2c3650}
.overlay{position:absolute;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:#0b1020b8;backdrop-filter:blur(8px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.modal{width:min(440px,100%);padding:30px;text-align:center;border:1px solid #ffffff24;border-radius:23px;background:linear-gradient(145deg,#222b40,#151b2b);box-shadow:0 25px 80px #0009}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.22em;color:#76eac9}.modal h1{font-size:clamp(29px,6vw,43px);line-height:1;margin:13px 0 10px;letter-spacing:-.04em}.modal p{font-size:13px;line-height:1.55;color:#abb4ca;margin:0 auto 21px;max-width:330px}.howto{display:flex;justify-content:center;gap:7px;margin:17px 0 22px}.howto span{width:36px;height:34px;display:grid;place-items:center;border:1px solid #ffffff20;border-radius:9px;background:#101726;font-size:11px;font-weight:900}.howto span:nth-child(1){color:#55dfcb}.howto span:nth-child(2){color:#9e86ff}.howto span:nth-child(3){color:#ffcb66}.howto span:nth-child(4){color:#ff758f}.primary{border:0;border-radius:12px;padding:13px 25px;background:linear-gradient(100deg,#67e6c1,#a5f5ad);color:#152131;font-size:12px;font-weight:1000;letter-spacing:.11em;cursor:pointer;box-shadow:0 8px 28px #68f0c044;transition:transform .15s}.primary:hover{transform:translateY(-2px)}.modal .tiny{font-size:10px;margin:13px 0 0;color:#7e89a2}.resultscore{font-size:12px;color:#d5dcf0;margin:-7px 0 20px}.countdown{position:absolute;inset:0;z-index:5;display:grid;place-items:center;font-size:90px;font-weight:1000;color:white;text-shadow:0 0 45px #68f0c0;pointer-events:none;opacity:0}.countdown.show{animation:count .7s ease-out}@keyframes count{0%{opacity:0;transform:scale(1.7)}25%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.7)}}
.reward-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}.reward-list[hidden]{display:none}.reward{min-height:84px;border:1px solid #ffffff20;border-radius:12px;background:#101726;color:#f5f4ff;padding:10px 7px;font-size:11px;font-weight:850;cursor:pointer;transition:transform .15s}.reward span{display:block;color:#9da7bf;font-size:9px;font-weight:600;line-height:1.35;margin-top:6px}.reward:hover{transform:translateY(-2px)}@media(max-width:640px){body{padding:0;display:block;background:#101624}.game{width:100%;min-height:100svh;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom);border-radius:0;border:0;display:flex;flex-direction:column}.topbar{height:56px;padding:0 15px}.brand{font-size:13px}.brandmark{width:31px;height:31px}.chip{font-size:9px;padding:7px 9px}.hud{min-height:74px;padding:10px 14px;grid-template-columns:1fr 42px 1fr;gap:8px}.fighterline{font-size:11px}.fighterline small{font-size:8px}.hp{height:8px;margin-top:7px}.hptext{font-size:9px}.vs{font-size:10px}.arena{height:clamp(210px,34svh,290px);min-height:210px}.scene-label{top:10px;left:12px;font-size:8px}.creature-name{left:12px;bottom:11px;font-size:9px}.creature-name.foe{right:12px}.rhythm{padding:12px 12px 15px;flex:1}.instruction{font-size:9px}.lane-board{height:clamp(150px,23svh,190px)}.lane .key{bottom:6px;width:32px;height:25px}.hitline{bottom:37px}.note{width:36px;height:17px}.stats{gap:12px}.stat label{font-size:8px}.stat strong{font-size:13px}.meter{width:75px}.status{font-size:9px;min-width:92px}.controls{padding:0 12px;height:48px;font-size:9px}.controlright button{font-size:9px;padding:7px 8px}.modal{padding:25px 20px}.countdown{font-size:75px}}
