<body>
<main class="game" id="game">
<header class="topbar"><div class="brand"><div class="brandmark">♫</div><div>BEATBEASTS<small>RHYTHM LEAGUE</small></div></div><div class="right-top"><div class="chip" id="runBadge">🎵 RUN 1 · PISO 1</div><button class="sound" id="soundBtn" aria-label="Toggle sound" title="Toggle sound">♫</button></div></header>
<section class="hud"><div class="fighter"><div class="fighterline"><span>TÚ · <span id="playerName">MIRA</span></span><small id="playerLevel">LV. 01</small></div><div class="hp"><span id="playerBar" style="width: 100%;"></span></div><div class="hptext"><b id="playerHP">100</b> / <span id="maxHpText">100</span> HP</div></div><div class="vs">VS<span id="floorRound">PISO 01</span></div><div class="fighter enemy"><div class="fighterline"><span>SALVAJE · <span id="enemyName">VOLTIGER</span></span><small id="enemyLevel">LV. 02</small></div><div class="hp"><span id="enemyBar" style="width: 100%;"></span></div><div class="hptext"><b id="enemyHP">100</b> / 100 HP</div></div></section>
<section class="arena"><canvas id="scene" aria-label="Two original creatures face off in a forest arena" width="762" height="235"></canvas><div class="scene-label"><i class="live-dot"></i>BOSQUE LUNAR <span style="opacity:.55">·</span> EN VIVO</div><div class="creature-name">TU COMPAÑERA <span style="color:#70edc7">GLOWPUP</span></div><div class="creature-name foe">SALVAJE <span id="sceneEnemy" style="color:#ff8c9c">VOLTIGER</span></div><div class="toast" id="toast">PERFECT!</div></section>
<section class="rhythm"><div class="rhythm-head"><div class="section-title">DUELO RÍTMICO <span style="color:#747f99">/</span> <span id="tempo">108 BPM</span></div><div class="instruction">Pulsa las notas en la línea <b>· A S D F</b></div></div><div class="lane-board" id="board"><div class="lane" data-lane="0"><div class="key">A</div></div><div class="lane" data-lane="1"><div class="key">S</div></div><div class="lane" data-lane="2"><div class="key">D</div></div><div class="lane" data-lane="3"><div class="key">F</div></div><div class="hitline"></div></div><div class="bottom"><div class="stats"><div class="stat"><label>PUNTOS</label><strong id="score">000000</strong></div><div class="stat"><label>COMBO</label><strong class="combo" id="combo">×0</strong><div class="meter"><span id="meter" style="width: 0%;"></span></div></div><div class="stat"><label>PRECISIÓN</label><strong id="accuracy">—</strong></div></div><div class="status" id="status">Ready when you are.</div></div></section>
<footer class="controls"><div><strong>TIP</strong> · Stay on the beat to power up your attacks.</div><div class="controlright"><span>OR</span><button data-lane="0">A</button><button data-lane="1">S</button><button data-lane="2">D</button><button data-lane="3">F</button></div></footer>
<div class="countdown" id="countdown"></div>
<div class="overlay" id="overlay"><div class="modal"><div class="eyebrow" id="modalEyebrow">UNA AVENTURA RÍTMICA</div><h1 id="modalTitle">¡QUE EMPIECE<br>EL RITMO!</h1><p id="modalText">Tu ritmo es tu mejor ataque. Acierta las notas, crea combos y supera a las criaturas salvajes. Cada victoria te hará más fuerte… y cada piso, más difícil.</p><div class="howto"><span>A</span><span>S</span><span>D</span><span>F</span></div><div class="reward-list" id="rewardList" hidden=""></div><button class="primary" id="startBtn">COMENZAR RUN&nbsp; →</button><p class="tiny" id="modalTiny">Teclado o toque · Activa el sonido para escuchar la música</p></div></div>
</main>
<script>
(()=>{'use strict';
const $=s=>document.querySelector(s), board=$('#board'), lanes=[...document.querySelectorAll('.lane')], canvas=$('#scene'),ctx=canvas.getContext('2d');
let running=false,started=false,muted=false,audio=null,notes=[],startAt=0,score=0,combo=0,best=0,hp=100,maxHp=100,foe=100,hits=0,judged=0,perfects=0,misses=0,toastTimer,attack=0,impact=0;
let runNo=1,floor=1,damageBoost=1,bpm=108,beat=60/108,foeMax=100,chartEnd=0,isGameOver=false;
const travel=1.75,keys=['a','s','d','f'], colors=['#55dfcb','#9e86ff','#ffcb66','#ff758f'];
const wilds=['VOLTIGER','MOSSQUATCH','EMBERKIT','MOONMOTH','CRAGHORN','BUBBLEBOP','THORNSNAP'];
const tunes=[0,2,4,7,4,2,0,2, 0,3,5,7,5,3,2,3],scale=[261.63,293.66,329.63,392,440,523.25,587.33,659.25];
function setHud(){ $('#playerHP').textContent=Math.ceil(hp);$('#maxHpText').textContent=maxHp;$('#enemyHP').textContent=Math.ceil(foe);$('#playerBar').style.width=(hp/maxHp*100)+'%';$('#enemyBar').style.width=(foe/foeMax*100)+'%';$('#score').textContent=String(score).padStart(6,'0');$('#combo').textContent='×'+combo;$('#meter').style.width=Math.min(100,combo*8)+'%';$('#accuracy').textContent=judged?Math.round(hits/judged*100)+'%':'—';$('#runBadge').textContent=`🎵 RUN ${runNo} · PISO ${floor}`;$('#floorRound').textContent=`PISO ${String(floor).padStart(2,'0')}`;$('#playerLevel').textContent=`LV. ${String(1+Math.floor(floor/2)).padStart(2,'0')}`;$('#enemyLevel').textContent=`LV. ${String(1+floor).padStart(2,'0')}`; }
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),650)}
function audioCtx(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}
function tone(freq,dur=.1,type='sine',vol=.06){if(muted)return;try{const a=audioCtx(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+dur);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+dur)}catch(e){}}
function musicNote(freq,time,dur,vol,type='triangle'){if(muted||!audio)return;try{const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(vol,time+.012);g.gain.exponentialRampToValueAtTime(.0001,time+dur);o.connect(g);g.connect(audio.destination);o.start(time);o.stop(time+dur+.02)}catch(e){}}
function musicStep(n){if(muted||!audio)return;const t=audio.currentTime+.015,step=n%16,root=[130.81,110,146.83,98][Math.floor(step/4)%4];if(step%4===0)musicNote(root,t,.25,.075,'sine');if(step%2===0)musicNote(70,t,.055,.022,'triangle');if(step%4===2)musicNote(1800,t,.035,.012,'square');musicNote(scale[tunes[step]],t,.17,.034,'triangle');if(step%4===0){musicNote(root*2,t,.28,.018,'sine');musicNote(root*2.5,t,.28,.014,'sine')}}
function makeChart(){notes=[];let seed=(741+floor*92821)>>>0;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};bpm=Math.min(176,108+Math.max(0,floor-1)*4);beat=60/bpm;foeMax=100+Math.max(0,floor-1)*18;foe=foeMax;$('#tempo').textContent=bpm+' BPM';const count=40+Math.min(16,(floor-1)*2),density=Math.min(.96,.72+(floor-1)*.025);for(let i=0;i<count;i++){if(rand()<density)notes.push({time:2.2+i*beat,lane:Math.floor(rand()*4),judged:false,el:null});if(floor>=4&&i%4===1&&rand()<Math.min(.55,(floor-2)*.07))notes.push({time:2.2+(i+.5)*beat,lane:Math.floor(rand()*4),judged:false,el:null})}notes.sort((a,b)=>a.time-b.time);chartEnd=2.2+count*beat}
function start(){if(running)return;audioCtx();if(isGameOver){runNo++;floor=1;hp=maxHp=100;damageBoost=1;score=0;isGameOver=false;$('#modalEyebrow').textContent='UNA NUEVA AVENTURA';$('#runBadge').textContent=`🎵 RUN ${runNo} · PISO 1`}$('#startBtn').style.display='';$('#rewardList').hidden=true;$('#overlay').classList.add('hidden');beginBattle()}
function beginBattle(){combo=best=hits=judged=perfects=misses=0;impact=attack=0;startAt=0;document.querySelectorAll('.note').forEach(n=>n.remove());const foeName=wilds[(floor-1)%wilds.length];$('#enemyName').textContent=foeName;$('#sceneEnemy').textContent=foeName;makeChart();setHud();$('#status').textContent='¡Encuentra el ritmo!';running=true;started=true;beatMark=-1;let n=3;const count=$('#countdown');const tick=()=>{if(!running)return;count.textContent=n>0?n:'¡YA!';count.classList.remove('show');void count.offsetWidth;count.classList.add('show');if(n===0){startAt=performance.now()/1000;$('#status').textContent='¡El ritmo es tuyo!';tone(440,.18,'triangle',.05)}else tone(300+n*70,.12,'sine',.04);n--;if(n>=-1)setTimeout(tick,700)};tick()}
function resetRun(){floor=1;hp=maxHp=100;damageBoost=1;score=0;isGameOver=false;beginBattle()}
function showRewards(){const list=$('#rewardList');list.innerHTML='';list.hidden=false;$('#startBtn').style.display='none';const options=[['💚','RECUPERAR','Cura 35 HP',()=>{hp=Math.min(maxHp,hp+35)}],['💎','CORAZÓN','+20 HP máximo y cura 20',()=>{maxHp+=20;hp=Math.min(maxHp,hp+20)}],['⚡','POTENCIAR','Tus golpes hacen +20% daño',()=>{damageBoost*=1.2}]];for(const [icon,title,desc,apply] of options){const button=document.createElement('button');button.className='reward';button.innerHTML=`${icon} ${title}<span>${desc}</span>`;button.addEventListener('click',()=>{apply();floor++;$('#overlay').classList.add('hidden');list.hidden=true;$('#startBtn').style.display='';beginBattle()},{once:true});list.appendChild(button)}}
function end(win){running=false;$('#overlay').classList.remove('hidden');$('#modalEyebrow').textContent=win?'VICTORIA · ELIGE TU RECOMPENSA':'FIN DE LA RUN';$('#modalTitle').innerHTML=win?'¡VICTORIA!<br>¡SIGUIENTE PISO!':'¡A ENTRENAR!';$('#modalText').textContent=win?`Superaste el piso ${floor}. El camino se acelera y los rivales se fortalecen: elige una mejora para continuar.`:`${$('#enemyName').textContent} te ha vencido en el piso ${floor}. Tu mejor combo fue ×${best}. ¡Una nueva run te espera!` ;$('#modalTiny').textContent=`Combo máximo ×${best} · Precisión ${judged?Math.round(hits/judged*100):0}% · ${score.toLocaleString()} puntos`;$('#status').textContent=win?'¡Piso superado!':'Run terminada.';if(win){showRewards()}else{isGameOver=true;$('#rewardList').hidden=true;$('#startBtn').style.display='';$('#startBtn').textContent='NUEVA RUN  ↻'}tone(win?660:180,.45,'triangle',.07);setHud()}
function hit(lane){if(!running)return;lanes[lane].classList.add('active');setTimeout(()=>lanes[lane].classList.remove('active'),110);const now=performance.now()/1000-startAt;let pick=null,delta=9;for(const note of notes){if(note.judged||note.lane!==lane)continue;const d=Math.abs(now-note.time);if(d<delta){delta=d;pick=note}}if(!pick||delta>.22){toast('OFF BEAT');tone(130,.07,'square',.025);return}pick.judged=true;judged++;hits++;combo++;best=Math.max(best,combo);if(delta<=.085){perfects++;score+=100+Math.min(combo,30)*3;foe=Math.max(0,foe-12*damageBoost);toast('¡PERFECTO!');tone([523,659,784,988][lane],.15,'triangle',.055);attack=1}else{score+=60+Math.min(combo,30)*2;foe=Math.max(0,foe-8*damageBoost);toast('¡BIEN!');tone([392,494,587,740][lane],.12,'triangle',.05);attack=.6}if(pick.el)pick.el.classList.add('hit');impact=1;setHud();if(foe<=0){setTimeout(()=>end(true),400)}}
