 function setPokemonSprite(img,p){img.alt=p[0];img.onerror=()=>{img.onerror=null;img.src=`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${p[1]}.png`};img.src=`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${p[1]}.png`}
 function renderMap(){const map=$('#routeMap'),row=$('#badgeRow');map.innerHTML='';row.innerHTML='';leaders.forEach((g,i)=>{const badge=document.createElement('span');badge.className='badge'+(badges.includes(i)?' earned':'');badge.title=`${g.name} · ${badges.includes(i)?'medalla conseguida':'pendiente'}`;badge.textContent=g.badge;row.appendChild(badge)});routeNodes.forEach((node,i)=>{const button=document.createElement('button');button.className='map-node '+(i<=currentNode?'done':i===currentNode+1?'current':'locked');button.disabled=i!==currentNode+1;button.innerHTML=`${node.kind==='GIMNASIO'?'🏟️':'🛤️'} <b>${node.name}</b>${node.kind}`;button.setAttribute('aria-label',`${node.kind}: ${node.name}${button.disabled?' (bloqueado)':' (disponible)'}`);if(!button.disabled)button.addEventListener('click',()=>selectNode(i));map.appendChild(button)});$('#mapLegend').textContent=currentNode>=routeNodes.length-1?'¡Kanto completado! Has conseguido todas las medallas.':`Siguiente: ${routeNodes[currentNode+1]?.kind} · ${routeNodes[currentNode+1]?.name}. Pulsa el nodo iluminado.`}
  function showMapScreen(){const panel=$('#mapPanel');panel.hidden=false;$('#rewardList').hidden=true;$('#startBtn').style.display=currentNode>=routeNodes.length-1?'':'none';if(currentNode>=routeNodes.length-1){$('#startBtn').textContent='NUEVA AVENTURA ↻';$('#modalEyebrow').textContent='¡CAMPEÓN DE KANTO!';$('#modalTitle').innerHTML='¡RUTA<br>COMPLETADA!';$('#modalText').textContent='Has derrotado a los ocho líderes de gimnasio y conquistado Kanto.'}else{$('#modalEyebrow').textContent='MAPA DE KANTO';$('#modalTitle').textContent='ELIGE TU CAMINO';$('#modalText').textContent='Avanza por las rutas, derrota a los líderes y gana sus ocho medallas. Cada victoria te permite elegir una mejora.'}renderMap();$('#overlay').classList.remove('hidden')}
  function selectNode(index){if(index!==currentNode+1||running)return;activeNode=index;floor=index+1;gymPokemonIndex=0;transitioning=false;$('#mapPanel').hidden=true;$('#overlay').classList.add('hidden');beginBattle()}
- function start(){if(running)return;audioCtx();if(isGameOver||currentNode>=routeNodes.length-1){runNo++;floor=1;hp=maxHp=180;damageBoost=1;guard=leech=0;score=0;currentNode=-1;activeNode=0;badges=[];playerPokemon=randomPokemon();isGameOver=false;$('#startBtn').textContent='VER MAPA  →'}showMapScreen()}
+ function start(){if(running)return;audioCtx();if(isGameOver||currentNode>=routeNodes.length-1){runNo++;floor=1;hp=maxHp=180;damageBoost=1;guard=leech=0;score=0;currentNode=-1;activeNode=0;badges=[];playerPokemon=randomPokemon();isGameOver=false;$('#startBtn').textContent='VER MAPA  →';setHud()}showMapScreen()}
 function beginBattle(){combo=best=hits=judged=perfects=misses=0;impact=attack=0;startAt=0;transitioning=false;teamDefeated=false;document.querySelectorAll('.note').forEach(n=>n.remove());const event=routeNodes[activeNode],leader=event.leader!==undefined?leaders[event.leader]:null,enemyPokemon=leader?leader.team[gymPokemonIndex]:randomPokemon(playerPokemon);$('#playerName').textContent=playerPokemon[0];$('#scenePlayer').textContent=playerPokemon[0];$('#enemyName').textContent=enemyPokemon[0];$('#sceneEnemy').textContent=enemyPokemon[0];$('#enemyRole').textContent=leader?leader.name:'SALVAJE';$('#biomeLabel').textContent=event.biome||biomes[Math.floor(Math.random()*biomes.length)];setPokemonSprite($('#playerSprite'),playerPokemon);setPokemonSprite($('#enemySprite'),enemyPokemon);makeChart();setHud();$('#status').textContent=leader?`${leader.name} te desafía · Pokémon ${gymPokemonIndex+1}/${leader.team.length}`:'¡Encuentra el ritmo!';running=true;started=true;beatMark=-1;let n=3;const count=$('#countdown');const tick=()=>{if(!running)return;count.textContent=n>0?n:'¡YA!';count.classList.remove('show');void count.offsetWidth;count.classList.add('show');if(n===0){startAt=performance.now()/1000;$('#status').textContent=leader?`¡A por ${enemyPokemon[0]}!`:'¡El ritmo es tuyo!';tone(440,.18,'triangle',.08)}else tone(300+n*70,.12,'sine',.05);n--;if(n>=-1)setTimeout(tick,700)};tick()}
 function resetRun(){floor=1;hp=maxHp=180;damageBoost=1;guard=leech=0;score=0;playerPokemon=randomPokemon();isGameOver=false;beginBattle()}
 function showRewards(){const list=$('#rewardList');list.innerHTML='';list.hidden=false;$('#startBtn').style.display='none';const pool=[['💚','POCIÓN','Cura 55 HP',()=>{hp=Math.min(maxHp,hp+55)}],['💎','MÁX. HP +30','Aumenta y recupera 30 HP',()=>{maxHp+=30;hp=Math.min(maxHp,hp+30)}],['⚡','ATAQUE +25%','Tus golpes hacen más daño',()=>{damageBoost*=1.25}],['🛡️','ESCUDO','Reduce 2 el daño al fallar (máx. 8)',()=>{guard=Math.min(8,guard+2)}],['✨','ABSORCIÓN','Recupera 2 HP con cada acierto',()=>{leech=Math.min(8,leech+2)}],['🧪','GRAN POCIÓN','Cura 90 HP',()=>{hp=Math.min(maxHp,hp+90)}],['💫','RITMO POTENTE','Tus golpes hacen +12% daño',()=>{damageBoost*=1.12}],['❤️','CORAZÓN','Aumenta 15 HP máx. y cura 40',()=>{maxHp+=15;hp=Math.min(maxHp,hp+40)}],['🛡️','BARRERA','Reduce 1 daño al fallar (máx. 8)',()=>{guard=Math.min(8,guard+1)}]];const options=[];while(options.length<3){const option=pool[Math.floor(Math.random()*pool.length)];if(!options.includes(option))options.push(option)}for(const [icon,title,desc,apply] of options){const button=document.createElement('button');button.className='reward';button.innerHTML=`${icon} ${title}<span>${desc}</span>`;button.addEventListener('click',()=>{apply();list.hidden=true;showMapScreen()},{once:true});list.appendChild(button)}}
 function end(win){running=false;transitioning=false;$('#overlay').classList.remove('hidden');$('#mapPanel').hidden=true;$('#modalEyebrow').textContent=win?'VICTORIA · ELIGE TU RECOMPENSA':'FIN DE LA RUN';$('#modalTitle').innerHTML=win?'¡VICTORIA!<br>¡SIGUIENTE PARADA!':'¡A ENTRENAR!';const event=routeNodes[activeNode],leader=event.leader!==undefined?leaders[event.leader]:null;if(win){currentNode=activeNode;if(leader&&!badges.includes(event.leader))badges.push(event.leader);if(currentNode===routeNodes.length-1)isGameOver=true}$('#modalText').textContent=win?(leader?`¡Derrotaste a ${leader.name} y ganaste la medalla ${leader.badge}! Elige una mejora y vuelve al mapa.`:`Superaste ${event.name}. Elige una mejora antes de continuar tu viaje por Kanto.`):`${$('#enemyName').textContent} te ha vencido en ${event.name}. Tu mejor combo fue ×${best}. ¡Puedes volver a intentarlo en una nueva aventura!`;$('#modalTiny').textContent=`Combo máximo ×${best} · Precisión ${judged?Math.round(hits/judged*100):0}% · ${score.toLocaleString()} puntos`;$('#status').textContent=win?'¡Parada superada!':'Run terminada.';if(win){showRewards()}else{isGameOver=true;$('#rewardList').hidden=true;$('#startBtn').style.display='';$('#startBtn').textContent='NUEVA AVENTURA ↻'}tone(win?660:180,.45,'triangle',.07);setHud()}

